Submission pipeline of the CodeDev tutor:
function grade(results: { passed: boolean }[]): { score: number; passed: boolean } {
  const ok = results.filter((r) => r.passed).length;
  return { score: results.length ? Math.round((100 * ok) / results.length) : 0, passed: ok === results.length && ok > 0 };
}

async function onSubmit(sub: Submission) {
  const results = await runner.runHiddenTests(sub);
  const result = grade(results);
  const feedback = await aiTutor.review(sub.code, results);   // shown as "AI tutor feedback"
  await db.submissions.save({ id: sub.id, score: result.score, passed: result.passed, aiFeedback: feedback.text });
}

Statement: "In this pipeline the AI tutor's review cannot change the learner's score."
